        manual_toc_5: '5. Extra Funktionen', manual_toc_6: '6. Kontoverwaltung', manual_toc_7: '7. Pläne und Preise', manual_toc_8: '8. Tipps und Tricks',
        manual_s1_title: 'Einführung', manual_s1_p1: 'Willkommen bei <strong class="text-purple-400">Alma do Livro</strong>! Diese App nutzt fortschrittliche künstliche Intelligenz, um Ihnen zu helfen, jedes Buch auf einzigartige Weise zu erkunden und zu verstehen.',
        manual_s1_p2: 'Mit Alma do Livro können Sie:', manual_s1_li1: 'Detaillierte Zusammenfassungen jedes Buches erhalten', manual_s1_li2: 'Charaktere, Themen und Symbolik analysieren', manual_s1_li3: 'Fiktive Charaktere interviewen',
        manual_s1_li4: 'Quiz erstellen, um Wissen zu testen', manual_s1_li5: 'Fortsetzungen und alternative Enden generieren', manual_s1_li6: 'Playlists, Film-Casting und vieles mehr entdecken',
        manual_s2_title: 'Erste Schritte', manual_s2_step1_title: 'Schritt 1: Konto erstellen', manual_s2_step1_text: 'Klicken Sie auf "Kostenlos Starten" und füllen Sie das Formular aus. Das kostenlose Konto gibt Zugang zu 10 Analysen pro Monat.',
        manual_s2_step2_title: 'Schritt 2: Anmelden', manual_s2_step2_text: 'Nach der Kontoerstellung melden Sie sich mit E-Mail und Passwort an, um auf den Buch-Explorer zuzugreifen.',
        manual_s2_step3_title: 'Schritt 3: Buch erkunden', manual_s2_step3_text: 'Im Explorer geben Sie den Titel des Buches ein, das Sie analysieren möchten. Klicken Sie auf "Buch erkunden" um zu starten!',
        manual_s3_title: 'Buch-Explorer', manual_s3_p1: 'Der Explorer ist die Hauptfunktion der App. Er ermöglicht die Analyse jedes veröffentlichten Buches mit künstlicher Intelligenz.',
        manual_s3_tip: '<strong>💡 Tipp:</strong> Die KI kennt Millionen von Büchern! Von Klassikern bis zu modernen Bestsellern.', manual_s3_analyses_title: '3.1 Verfügbare Analysen',
        manual_analysis_summary: 'Zusammenfassung', manual_analysis_summary_desc: 'Vollständige und detaillierte Synopsis des Buches', manual_analysis_characters: 'Charaktere', manual_analysis_characters_desc: 'Liste und Analyse aller Charaktere',
        manual_analysis_themes: 'Themen', manual_analysis_themes_desc: 'Hauptthemen und Botschaften des Werks', manual_analysis_world: 'Welt', manual_analysis_world_desc: 'Setting, Epoche und Atmosphäre',
        manual_analysis_style: 'Stil', manual_analysis_style_desc: 'Analyse des literarischen Stils des Autors', manual_analysis_quotes: 'Zitate', manual_analysis_quotes_desc: 'Berühmte und unvergessliche Zitate',
        manual_analysis_similar: 'Ähnliche', manual_analysis_similar_desc: 'Empfehlungen für ähnliche Bücher', manual_analysis_symbolism: 'Symbolik', manual_analysis_symbolism_desc: 'Symbole und verborgene Bedeutungen',
        manual_s4_title: 'Interaktive Funktionen', manual_s4_p1: 'Dies sind die unterhaltsamsten Funktionen von Alma do Livro! Verfügbar in Pro- und Premium-Plänen.',
        manual_s4_interviews_title: '4.1 Charakter-Interviews', manual_s4_interviews_desc: 'Chatten Sie direkt mit jedem Charakter aus dem Buch! Die KI übernimmt die Persönlichkeit des Charakters.',
        manual_example: 'Beispiel:', manual_s4_interviews_ex1: '"Sancho, was denkst du wirklich über Don Quijote?"', manual_s4_interviews_ex2: '"Ah, mein Herr ist ein Mann mit großem Herzen, auch wenn er manchmal Windmühlen mit Riesen verwechselt..."',
        manual_s4_quiz_title: '4.2 Interaktives Quiz', manual_s4_quiz_desc: 'Testen Sie Ihr Wissen über das Buch mit Multiple-Choice-Fragen, die von KI generiert werden.',
        manual_s4_quiz_easy: '<strong>Leicht:</strong> Fragen zu grundlegenden Fakten', manual_s4_quiz_medium: '<strong>Mittel:</strong> Erfordert gutes Verständnis der Geschichte', manual_s4_quiz_hard: '<strong>Schwer:</strong> Details, Symbolik und tiefe Analyse',
        manual_s4_cont_title: '4.3 Geschichtsfortsetzungen', manual_s4_cont_desc: 'Generieren Sie neue Inhalte für das Buch unter Beibehaltung des Stils des Originalautors.',
        manual_s4_cont_chapter: '<strong>Nächstes Kapitel:</strong> Setzt die Geschichte dort fort, wo sie aufgehört hat', manual_s4_cont_epilogue: '<strong>Epilog:</strong> Was nach dem Ende passierte', manual_s4_cont_sequel: '<strong>Fortsetzung:</strong> Beginn eines neuen Buches in derselben Serie',
        manual_s4_alt_title: '4.4 Alternative Enden', manual_s4_alt_desc: 'Erkunden Sie "Was wäre wenn...?"-Szenarien und entdecken Sie, wie die Geschichte anders hätte sein können.', manual_s4_alt_ex: '"Was wäre, wenn Romeo rechtzeitig angekommen wäre, um Julia aufwachen zu sehen?"',
