        manual_extra_trailer: 'Filmtrailer', manual_extra_trailer_desc: 'Beschreibender Text für einen Filmtrailer', manual_extra_casting: 'Film-Casting', manual_extra_casting_desc: 'Schauspielervorschläge für jeden Charakter',
