// Detect browser language and map to supported languages
function detectBrowserLanguage() {
    const browserLang = navigator.language || navigator.userLanguage || 'pt-PT';
    const langCode = browserLang.toLowerCase();
    
    // Map browser language codes to our supported languages
    const languageMap = {
        'pt-pt': 'pt-pt',
        'pt-br': 'pt-br',
        'pt': 'pt-pt',  // Default Portuguese to PT-PT
        'en-us': 'en',
        'en-gb': 'en',
        'en': 'en',
        'fr-fr': 'fr',
        'fr': 'fr',
        'de-de': 'de',
        'de': 'de',
        'it-it': 'it',
        'it': 'it',
        'es-es': 'es',
        'es-mx': 'es',
        'es-ar': 'es',
        'es': 'es'
    };
    
    // Try exact match first
    if (languageMap[langCode]) {
        return languageMap[langCode];
    }
    
    // Try base language (e.g., 'en' from 'en-US')
    const baseLang = langCode.split('-')[0];
    if (languageMap[baseLang]) {
        return languageMap[baseLang];
    }
    
    // Default to Portuguese (Portugal)
    return 'pt-pt';
}

// Get saved language or detect from browser
function getInitialLanguage() {
    const saved = localStorage.getItem('uiLanguage');
    if (saved && translations[saved]) {
        return saved;
    }
    
    // First visit - detect from browser
    const detected = detectBrowserLanguage();
    localStorage.setItem('uiLanguage', detected);
    return detected;
}

let currentUILang = getInitialLanguage();

function t(key) {
    return translations[currentUILang]?.[key] || translations['pt-pt'][key] || key;
}

// Get detected language info for display
function getLanguageInfo() {
    const browserLang = navigator.language || navigator.userLanguage || 'unknown';
    return {
        browser: browserLang,
        detected: detectBrowserLanguage(),
        current: currentUILang,
        isAutoDetected: !localStorage.getItem('uiLanguage_manual')
    };
}

function changeUILanguage(lang, isManual = true) {
    currentUILang = lang;
    localStorage.setItem('uiLanguage', lang);
    if (isManual) {
        localStorage.setItem('uiLanguage_manual', 'true');
    }
    applyTranslations();
    const sel = document.getElementById('uiLangSelect');
    if (sel) sel.value = lang;
}

// Reset to auto-detect
function resetLanguageToAuto() {
    localStorage.removeItem('uiLanguage');
    localStorage.removeItem('uiLanguage_manual');
    const detected = detectBrowserLanguage();
    currentUILang = detected;
    localStorage.setItem('uiLanguage', detected);
    applyTranslations();
    const sel = document.getElementById('uiLangSelect');
    if (sel) sel.value = detected;
    return detected;
}

function applyTranslations() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        el.textContent = t(key);
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
        const key = el.getAttribute('data-i18n-html');
        el.innerHTML = t(key);
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        el.placeholder = t(el.getAttribute('data-i18n-placeholder'));
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        el.title = t(el.getAttribute('data-i18n-title'));
    });
    // Update style select
    const styleSelect = document.getElementById('style');
    if (styleSelect) {
        const map = {romance:'s_romance',ficcao_cientifica:'s_scifi',fantasia:'s_fantasy',terror:'s_horror',
            policial:'s_crime',infantil:'s_children',aventura:'s_adventure',drama:'s_drama',comedia:'s_comedy',
            historico:'s_historical',suspense:'s_suspense',autobiografia:'s_autobiography',tecnico:'s_technical',
            tutorial:'s_tutorial',educacional:'s_educational',autoajuda:'s_selfhelp'};
        Array.from(styleSelect.options).forEach(opt => {
            if (map[opt.value]) opt.textContent = t(map[opt.value]);
        });
    }
    // Update pages select
    const pagesSelect = document.getElementById('numPages');
    if (pagesSelect) {
        const map = {'10':'p_10','20':'p_20','50':'p_50','100':'p_100','150':'p_150','200':'p_200'};
        Array.from(pagesSelect.options).forEach(opt => {
            if (map[opt.value]) opt.textContent = t(map[opt.value]);
        });
    }
}

// Initialize on load
function initI18n() {
    const sel = document.getElementById('uiLangSelect');
    if (sel) {
        sel.value = currentUILang;
        sel.addEventListener('change', (e) => changeUILanguage(e.target.value));
    }
    applyTranslations();
}

// Run immediately if DOM is ready, otherwise wait for DOMContentLoaded
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initI18n);
} else {
    initI18n();
}
